(* [comment removed for export] *)
Definition dg_mem (m : word -> option byte) (j8 : list byte) (s0' s1' s2' s3' : word) (len Kv : Z) (bs : list byte) : Prop :=
  stk rsegs m (SP0 - 48) (SP0 - 48) /\
  rw_cells rsegs m (SP0 - 48) [CB 8 j8; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] /\
  munch DG_W m0 m /\ wmono rsegs m0 m /\ mem_inv rsegs m /\
  u8arr rsegs m buf bs /\ length bs = 21%nat /\
  rw_cells rsegs m lenp [C4 (Z_to_bv 64 len)] /\ rw_cells rsegs m kp [C4 (Z_to_bv 64 Kv)].

Ltac dg_mem_intro H := destruct H as (ST & FR & MU & WM & MI & BU & BL & LE & KC); unfold DG_W in MU.

Lemma dg_ret' : forall t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' s0' s1' s2' s3' t3' t4' t5' t6' (m : word -> option byte) j8 (res len kappa Ks : Z) (bs : list byte),
  dg_mem m j8 s0' s1' s2' s3' len (Ks + kappa) bs -> (1 <= len <= 21)%Z -> (-18 <= kappa <= 2)%Z ->
  a0' = Z_to_bv 64 res -> (res = 0 \/ res = 1)%Z -> (48 <= SP0 < 2 ^ 47)%Z ->
