(* [comment removed for export] *)
Lemma dg_rw2_loop : forall (n : nat) (D r one len : Z) t0' t1' t2' a0' a2' a3' a5' a7' s0' s1' s2' s3' t3' t5' t6' (m : word -> option byte) j8 (kappa Ks : Z) (bs : list byte),
  Z.to_nat (D - r) = n ->
  dg_mem m j8 s0' s1' s2' s3' len (Ks + kappa) bs -> (1 <= len <= 21)%Z -> (-18 <= kappa <= 2)%Z ->
  (0 <= r)%Z -> (1 <= one)%Z -> (r + one <= D)%Z -> (D < 2 ^ 64)%Z ->
  evt rsegs (dg_post Ks) (MS (mkR ra (Z_to_bv 64 (SP0 - 48)) gp tp t0' t1' t2' s0' s1' a0' (Z_to_bv 64 one) a2' a3' (Z_to_bv 64 r) a5' (Z_to_bv 64 (buf + len)) a7'
