  evt rsegs (dg_post Ks) (MS (mkR ra (Z_to_bv 64 (SP0 - 48)) gp tp (Z_to_bv 64 kp) (Z_to_bv 64 (2 ^ 32 - 1)) (Z_to_bv 64 (2 ^ s - 1)) s0' s1' (Z_to_bv 64 D) (Z_to_bv 64 (2 ^ s)) a2' a3'
